// 1. 获取输入数据
const inputData = $input.first().json;

// 2. 定义声音映射
const speakerMap = {
  老杨: "zh_male_dayixiansheng_v2_saturn_bigtts",
  小李: "zh_female_mizaitongxue_v2_saturn_bigtts",
};

// 3. 自定义 UUID v4 生成函数 (解决 crypto 缺失问题)
function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c == "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// 4. 构建输出结构
const result = {
  taskId: uuidv4(), // 调用自定义函数
  inputId: "朵朵的职场攻略-20260120",
  action: 3,
  nlpTexts: (inputData.output || []).map((item) => ({
    text: item.text,
    speaker:
      speakerMap[item.speaker] || "zh_male_dayixiansheng_v2_saturn_bigtts",
  })),
  speakerInfo: {
    randomOrder: false,
  },
  audioConfig: {
    format: "mp3",
    sampleRate: 24000,
  },
  useHeadMusic: false,
  useTailMusic: false,
  callbackUrl: $execution.resumeUrl,
};

// 5. 返回结果
return { json: result };

